import {LABELS,DIFFICULTIES,isAddition,createDresses,dressComplete,createSacks,createSackHunt,alignTree,finishTree,OperationHistory,nextOperation,createTree,activeNodes,splitNode,mergeNodes,removeNodes,circleNode,treeComplete,createClimb,setClimbStart,addJump,crossClimbStart,branchClimb,finishClimb,sum} from './engine.js';
const $=s=>document.querySelector(s),app=$('#app'),dialog=$('#editor');
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let history,solved=0,storageWarning=false;try{history=new OperationHistory(JSON.parse(localStorage.getItem('oaoa-operations-v1')||'{}'));solved=Number(localStorage.getItem('oaoa-solved')||0)}catch{history=new OperationHistory();storageWarning=true}
let playerSchool=localStorage.getItem('oaoa-school')||DEFAULT_SCHOOL;
let playerName=localStorage.getItem('oaoa-name')||'',playerRoom=localStorage.getItem('oaoa-room')||'3A',liveSession=null,record=null,recording=false,recordError='',startedPerf=null,initialElapsed=0,timerStopped=null,starting=false,teacherSecret='',weeklyData=null;
let wordSession=null;
let mode='add',digits=2,difficulty=1,difficultyByMode={},op=null,state=null,selected=[],undo=[],awarded=false,exercise=0,bag=[],zoom=1,editorAction=null,demo=false;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function saveHistory(){try{localStorage.setItem('oaoa-operations-v1',JSON.stringify(history.serialize()));localStorage.setItem('oaoa-solved',String(solved))}catch{storageWarning=true;toast('El navegador no permite guardar el historial. En esta sesión no repetiremos operaciones, pero podrían repetirse al recargar.')}}
function heroArt(){return `<div class="hero-art static-school-pair"><img src="${window.OAOA_ASSETS?.['/assets/art/school-pair-static-v6.webp']||'/assets/art/school-pair-static-v6.webp'}" alt="Dos compañeros con la camiseta roja y el pantalón azul marino del colegio" width="1200" height="1000" fetchpriority="high"><span class="party-badge">¡Una misión, muchos caminos!</span></div>`}
function home(){op=null;wordSession=null;app.innerHTML=`<section class="hero pixel-hero"><div class="pixel-hero-copy"><span class="eyebrow">RUTAS DE CÁLCULO · OAOA</span><h1>Aventuras matemáticas en<br><em>San Vicente<br>de Paúl</em></h1><p>Elige tu misión. Piensa, construye y encuentra tu camino.</p><a class="primary hero-play" href="#misiones">▶ Elegir misión</a></div>${heroArt()}</section><section class="setup" id="misiones"><div><span class="eyebrow">PREPARA TU AVENTURA</span><h2>Elige tu misión</h2><p>Elige una ruta y un nivel.</p></div><div class="level-choice" role="group" aria-label="Dificultad">${DIFFICULTIES.map(l=>`<button data-difficulty="${l.id}" aria-pressed="${difficulty===l.id}">${l.id} · ${l.label}<small>${mode==='multiply'?MULTIPLICATION_LEVELS[l.id-1]:l.digits+' cifras'}</small></button>`).join('')}</div></section><section class="routes">${Object.entries(LABELS).map(([key,title],i)=>`<button class="route r${i} ${mode===key?'chosen':''}" data-mode="${key}" aria-pressed="${mode===key}"><span class="route-icon">${['📖','🌳','🌿','🧗','👗','💰','🎯','🔵'][i]}</span><span class="route-number">0${i+1}</span><h3>${title}</h3><p>${['Lee, representa, calcula y responde.','Separa y junta.','Rodea, separa y tacha.','Escribe tus saltos.','Suma en cada vestido.','Junta, calcula y estima.','Encuentra los sacos de la meta.','Tapones y bolas, diagrama y veces.'][i]}</p><span class="route-bottom">${mode===key?'✓ Ruta elegida':'Elegir esta ruta →'}</span></button>`).join('')}</section><section class="player-setup"><label>Colegio<select id="player-school">${schoolOptions(playerSchool)}</select></label><label>Tu nombre o alias<input id="player-name" value="${esc(playerName)}" maxlength="24" minlength="2" placeholder="Ej.: Leo Panda" autocomplete="off"></label><label>Tu curso<select id="player-course">${courseOptions(playerRoom[0])}</select></label><label>Tu clase<select id="player-room">${classOptions(playerRoom)}</select></label></section><section class="launch"><label class="mix"><input id="mix" type="checkbox" ${mode==='mixed'?'checked':''}> Mezclar todas las rutas</label><button id="begin" class="primary">¡Jugar! →</button><span class="personal">✦ ${solved} operaciones completadas en este navegador</span></section>`;
 const signedIn=window.oaoaAccount;if(signedIn){$('#player-school').disabled=true;$('#player-name').disabled=true;$('#player-course').disabled=true;$('#player-room').disabled=true}app.querySelectorAll('[data-difficulty]').forEach(b=>b.onclick=()=>{difficulty=Number(b.dataset.difficulty);difficultyByMode[mode]=difficulty;digits=DIFFICULTIES[difficulty-1].digits;home()});app.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;difficulty=difficultyByMode[mode]||1;digits=DIFFICULTIES[difficulty-1].digits;home()});$('#mix').onchange=e=>{mode=e.target.checked?'mixed':'add';home()};$('#player-school').onchange=e=>{playerSchool=e.target.value;localStorage.setItem('oaoa-school',playerSchool)};$('#player-name').oninput=e=>playerName=e.target.value;$('#player-course').onchange=e=>{playerRoom=e.target.value+'A';home()};$('#player-room').onchange=e=>playerRoom=e.target.value;$('#begin').onclick=()=>newExercise();}
function pickedMode(){if(mode!=='mixed')return mode;if(!bag.length)bag=Object.keys(LABELS).sort(()=>Math.random()-.5);return bag.pop()}
function courseOptions(selected){return ['1','2','3','4','5','6'].map(c=>`<option value="${c}" ${c===String(selected)?'selected':''}>${c}.º Primaria</option>`).join('')}
function classOptions(selected,all=false){const grades=all?['1','2','3','4','5','6']:[String(selected)[0]];return grades.flatMap(g=>['A','B','C','D'].map(c=>g+c)).map(c=>`<option value="${c}" ${c===selected?'selected':''}>${c[0]}º${c[1]}</option>`).join('')}
function rankClassOptions(course,selected=''){if(course==='all')return '<option value="all">Todas las clases</option>';return `<option value="${course}">Todo ${course}.º</option>`+classOptions(selected.length===2?selected:course)}
async function api(body){const response=await fetch('/api/math',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await response.json();if(!response.ok)throw Error(data.error||'No se ha podido conectar.');return data}
async function newExercise(){if(starting)return;playerName=playerName.trim();if(playerName.length<2){toast('Escribe tu nombre antes de jugar.');$('#player-name')?.focus();return}starting=true;const begin=$('#begin')||$('#next');if(begin){begin.disabled=true;begin.textContent='Preparando…'}try{const candidate=nextOperation(pickedMode(),digits,history,difficulty);saveHistory();const data=await api({action:'start',name:playerName,school:playerSchool,room:playerRoom,mode:candidate.mode,level:difficulty,a:candidate.a,b:candidate.b});liveSession={id:data.id,elapsedMs:data.elapsedMs};localStorage.setItem('oaoa-name',playerName);localStorage.setItem('oaoa-room',playerRoom);wordSession=null;op=candidate;exercise++;awarded=false;demo=false;record=null;recordError='';recording=false;startState()}catch(e){toast(e.message);if(begin){begin.disabled=false;begin.textContent=op?'Otra operación →':'¡Jugar! →'}}finally{starting=false}}
function elapsedNow(){if(timerStopped!==null)return timerStopped;return startedPerf===null?0:initialElapsed+performance.now()-startedPerf}
function clockText(ms){const seconds=Math.max(0,Math.floor(ms/1000));return `${Math.floor(seconds/60)}:${String(seconds%60).padStart(2,'0')}`}
function updateClock(){if(wordSession?.stage==='calculate'&&!document.querySelector('#word-context')&&document.querySelector('.work-head'))document.querySelector('.work-head').insertAdjacentHTML('beforebegin',`<section id="word-context" class="word-context"><span class="eyebrow">3 · CALCULA A TU MANERA</span><p>${esc(wordSession.problem.text)}</p></section>`);const clock=$('#game-clock');if(clock)clock.textContent=demo?'📖 Ejemplo':`⏱ ${clockText(elapsedNow())}`}
async function saveRecord(){if(!liveSession||demo)return;const id=liveSession.id,actions=wordSession?structuredClone([...wordSession.steps,...state.actions,{type:'problemAnswer',answer:wordSession.answer}]):structuredClone(state.actions);recording=true;recordError='';updateRecord();try{const saved=await api({action:'finish',id,actions});if(liveSession?.id!==id)return;record=saved;timerStopped=saved.seconds*1000}catch(e){if(liveSession?.id===id)recordError=e.message}finally{if(liveSession?.id===id){recording=false;updateRecord();updateClock()}}}
function updateRecord(){const box=$('#record-status');if(!box)return;box.innerHTML=demo?'':recording?'<span>Guardando tus puntos…</span>':record?`<strong>⭐ +${record.points} puntos</strong><span>${record.base} por completar + ${record.bonus} por rapidez</span><button id="result-ranking" class="secondary">🏆 Ver ranking</button>`:recordError?`<span class="save-error">${esc(recordError)}</span><button id="retry-record" class="secondary">Guardar otra vez</button>`:'';const retry=$('#retry-record');if(retry)retry.onclick=saveRecord;const ranking=$('#result-ranking');if(ranking)ranking.onclick=()=>showRanking();const next=$('#next');if(next)next.disabled=recording}
setInterval(()=>{if(op&&!demo&&(wordSession?!wordSession.answer:!done()))updateClock()},200);
function startState(){if(op.mode==='problems'){wordSession={seed:op,problem:wordProblem(op),stage:'diagram',model:'parts',values:['','',''],steps:[]};startedPerf=performance.now();initialElapsed=liveSession?.elapsedMs||0;timerStopped=null;return wordWorkspace()}if(!awarded&&!wordSession){startedPerf=demo?null:performance.now();initialElapsed=liveSession?.elapsedMs||0;timerStopped=null}state=op.mode==='multiply'?createMultiplication(op):op.mode==='sackhunt'?createSackHunt(op):op.mode==='dresses'?createDresses(op):op.mode==='sacks'?createSacks(op):op.mode==='climb'?createClimb(op,true):createTree(op);selected=[];undo=[];zoom=window.innerWidth<650?.2:.9;workspace();window.scrollTo({top:0,behavior:'smooth'})}
function done(){if(wordSession&&wordSession.stage!=='calculate')return Number.isSafeInteger(wordSession.answer);return op.mode==='dresses'?dressComplete(state):['sacks','climb','sackhunt','multiply'].includes(op.mode)?state.finished:treeComplete(state)}
function commit(next){const action=next.actions?.at(-1)?.type;const completeNow=next.op.mode==='dresses'?dressComplete(next):['sacks','climb','sackhunt','multiply'].includes(next.op.mode)?next.finished:treeComplete(next);if(!['circle','cross','branch'].includes(action))sound(completeNow?'complete':'correct');undo.push(structuredClone(state));state=next;selected=[];if(done()&&wordSession){wordSession.stage='answer';return wordWorkspace()}if(done()&&!awarded){timerStopped=elapsedNow();awarded=true;if(!demo){solved++;saveHistory();void saveRecord()}toast('¡Camino conseguido! ¡Muy bien! ✨')}workspace();if(!done())setTimeout(()=>{const box=$('#graph-scroll');if(box)box.scrollTop=box.scrollHeight},30)}
function workspace(){if(wordSession&&wordSession.stage!=='calculate')return wordWorkspace();if(op.mode==='multiply')return multiplicationWorkspace();if(['dresses','sacks','sackhunt'].includes(op.mode))return extraWorkspace();const complete=done();app.innerHTML=`<section class="work-head"><div><span class="eyebrow">${demo?'EJEMPLO PARA EXPLORAR':`RUTA ${exercise} · NIVEL ${difficulty} · ${digits} CIFRAS`}</span><h1>${LABELS[op.mode]}</h1><span id="game-clock" class="game-clock" role="timer" aria-label="Tiempo de la operación"></span><p>${op.mode==='climb'?'Escribe tu camino.':op.mode==='subtract'?'Rodea, descompón y tacha partes dentro de tu árbol.':'Descompón como quieras. Después reúne las ramas para hallar el total.'}</p></div><div class="operation" aria-label="Operación">${op.a}<span>${op.mode==='add'?'+':'−'}</span>${op.b}<span>=</span><strong>${complete?(op.mode==='add'?op.a+op.b:op.a-op.b):'?'}</strong></div></section><div class="work-grid"><section class="workspace"><div class="workspace-top"><span>${op.mode==='climb'?'🧗 MI CAMINO':'🌳 TU ÁRBOL, TU MANERA'}</span><div>${op.mode!=='climb'?'<button id="arrange" title="Ordenar los nodos en filas">Ordenar</button><button id="fit" title="Ver el árbol completo">Ver todo</button><button id="zoom-out" aria-label="Alejar árbol">−</button><button id="zoom-in" aria-label="Acercar árbol">+</button>':''}<button id="undo" ${!undo.length?'disabled':''}>↶ Deshacer</button></div></div>${op.mode==='climb'?climbHtml():`<div class="diagram-legend"><span>○ Rodeado: lo voy a descomponer</span><span>╱ Tachado: ya lo he quitado</span></div><div id="graph-scroll" class="graph-scroll" tabindex="0" aria-label="Árbol interactivo; puedes desplazar el dibujo"><svg id="graph" role="group" aria-label="Árbol de cálculo"></svg></div><p class="graph-help">Pulsa números para seleccionarlos. Arrástralos para dar forma al árbol. Usa las flechas del teclado sobre un nodo para moverlo.</p>`}<div id="selection-bar"></div>${op.mode==='subtract'&&state.removed===op.b&&!complete?`<form id="tree-answer-form">${field('Resultado de la resta','tree-answer')}<button class="primary">Escribir resultado ✓</button><p id="tree-answer-error" role="alert"></p></form>`:''}${complete?`<div class="success">${celebrationHtml()}<span>✦ ¡BIEN HECHO!</span><h2>¡Lo has conseguido!</h2><p>${op.mode==='climb'?`${op.b} + ${op.a-op.b} = ${op.a}. Los saltos suman la diferencia.`:'Tu camino funciona.'}</p><div id="record-status" class="record-status" aria-live="polite"></div><div class="actions"><button id="next" class="primary">Otra operación →</button><button id="another" class="secondary">Otra forma</button></div></div>`:''}</section><aside class="toolbox"><span class="eyebrow">TU CAJA DE HERRAMIENTAS</span><h2>${complete?'Lo has construido tú.':'¿Cuál es tu siguiente idea?'}</h2>${op.mode==='climb'?`<p></p>`:`<div class="tools"><button id="circle" ${op.mode!=='subtract'?'hidden':''}>○ Rodear</button><button id="split">🌿 Separar</button><button id="merge">＋ Juntar</button><button id="remaining" ${op.mode!=='subtract'?'hidden':''}>＋ Juntar sin tachar</button><button id="remove" ${op.mode!=='subtract'?'hidden':''}>╱ Tachar</button></div><p class="hint">Selecciona un número para rodearlo o abrir sus ramas. Selecciona varios para reunirlos o tacharlos juntos.</p>`}${op.mode==='subtract'?`<div class="remove-progress"><small>TACHADO</small><b>${state.removed} <span>de ${op.b}</span></b><div><i style="width:${state.removed/op.b*100}%"></i></div><p>${state.removed===op.b?'Ya está todo tachado. Reúne las partes que quedan.':`Faltan ${op.b-state.removed} por tachar. Pueden estar en ramas distintas.`}</p></div>`:''}<button id="idea" class="idea">💡 Una pista, por favor</button><div class="log"><h3>Mis pasos</h3>${state.log.length?`<ol>${state.log.map(l=>`<li>${esc(l)}</li>`).join('')}</ol>`:'<p>Tus pasos aparecerán aquí. No hace falta seguir una única receta.</p>'}</div></aside></div>`;
 $('#undo').onclick=()=>{if(undo.length){state=undo.pop();selected=[];workspace()}};if(complete){$('#next').onclick=newExercise;$('#another').onclick=startState}
 $('#idea').onclick=()=>toast(op.mode==='add'?'Puedes separar decenas y unidades, partir un número por la mitad o crear una cantidad redonda. ¡Tú decides!':op.mode==='subtract'?`Busca las partes de ${op.b} dentro de ${op.a}. Puedes quitar primero decenas o unidades, y seguir abriendo ramas.`:`Puedes ir a la próxima decena, a una centena o elegir otro salto. No es obligatorio un único recorrido.`);
 if(op.mode==='climb'){bindClimb()}else{bindTree();renderGraph();updateSelection()}const answerForm=$('#tree-answer-form');if(answerForm)answerForm.onsubmit=e=>{e.preventDefault();try{commit(finishTree(state,values(['tree-answer'])[0]))}catch(e){sound('wrong');$('#tree-answer-error').textContent=e.message}};simplifyWorkspace();if(op.mode==='climb')alignClimbBranches();updateClock();if(complete)updateRecord()}
function simplifyWorkspace(){
 const workspace=$('.workspace'),tools=$('.tools');
 if(tools){const dock=document.createElement('div');dock.className='action-dock';$('.workspace-top').after(dock);dock.append(tools);const progress=$('.remove-progress');if(progress)dock.append(progress)}
 const log=$('.log');if(log){const details=document.createElement('details');details.className='steps-details';const summary=document.createElement('summary');summary.textContent='Mis pasos';details.append(summary);log.before(details);details.append(log)}
 const idea=$('#idea');if(idea)idea.textContent='💡 Ayuda';
 $('#editor-submit').textContent='Listo ✓';
}
function updateSelection(){if(!op||op.mode==='climb')return;const ns=selected.map(id=>state.nodes.find(n=>n.id===id)).filter(Boolean);$('#selection-bar').innerHTML=ns.length?`<span>Seleccionado: <b>${ns.map(n=>n.value).join(' + ')}</b></span><button id="clear-selection">Quitar selección</button><div class="quick-actions">${ns.length===1?`<button data-quick="split">Descomponer</button>${op.mode==='subtract'?'<button data-quick="circle">○ Rodear</button>':''}`:''}${ns.length>1?'<button data-quick="merge">＋ Reunir</button>':''}${op.mode==='subtract'&&state.removed<op.b?'<button data-quick="remove">╱ Tachar partes</button>':''}</div>`:'<span>Selecciona los números con los que quieres trabajar.</span>';const clear=$('#clear-selection');if(clear)clear.onclick=()=>{selected=[];renderGraph();updateSelection()};$('#split').disabled=ns.length!==1||done();$('#circle').disabled=ns.length!==1||done();const remainingReady=op.mode==='subtract'&&state.removed===op.b&&activeNodes(state).length>=2&&!done();$('#merge').disabled=(ns.length<2&&!remainingReady)||done();$('#merge').textContent=remainingReady?'＋ Juntar lo que queda':'＋ Juntar';$('#remove').disabled=!ns.length||state.removed>=op.b||done();$('#remaining').disabled=op.mode!=='subtract'||state.removed!==op.b||activeNodes(state).length<2||done();$('#selection-bar').querySelectorAll('[data-quick]').forEach(b=>{b.disabled=done();b.onclick=()=>$('#'+b.dataset.quick).click()})}
function branchSigns(){const signs=new Map();const put=ns=>{if(ns.length<2)return;const sorted=[...ns].sort((a,b)=>a.x-b.x);for(let i=0;i<sorted.length-1;i++){const a=sorted[i],b=sorted[i+1];if(Math.abs(a.y-b.y)>45)continue;const x=(a.x+b.x)/2,y=(a.y+b.y)/2+9;signs.set(Math.round(x)+':'+Math.round(y),`<text class="branch-sign" x="${x}" y="${y}" text-anchor="middle">+</text>`)}};for(const n of state.nodes){put(state.edges.filter(e=>e[0]===n.id).map(e=>state.nodes.find(v=>v.id===e[1])));}return [...signs.values()].join('')}
function renderGraph(){const svg=$('#graph');if(!svg)return;const height=Math.max(340,...state.nodes.map(n=>n.y+90));const minX=Math.max(0,Math.min(...state.nodes.map(n=>n.x))-65),maxX=Math.min(900,Math.max(...state.nodes.map(n=>n.x))+65);const width=maxX-minX;svg.setAttribute('viewBox',`${minX} 0 ${width} ${height}`);const displayWidth=Math.max(Math.min($('#graph-scroll').clientWidth,width),width*zoom);svg.style.width=`${displayWidth}px`;svg.style.height=`${height*displayWidth/width}px`;svg.innerHTML=`<defs><pattern id="dots" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="3" cy="3" r="1" fill="#e3e9d9"/></pattern></defs><rect width="900" height="${height}" fill="#fffefa"/>${state.edges.map(([a,b])=>{const p=state.nodes.find(n=>n.id===a),c=state.nodes.find(n=>n.id===b);return `<path d="M${p.x} ${p.y+(p.circled&&op.mode==='subtract'?35:23)} L${c.x} ${c.y-(c.circled&&op.mode==='subtract'?35:25)}" fill="none" stroke="#b4c8a7" stroke-width="3"/>`}).join('')}${op.mode==='subtract'?`<text class="operation-sign" x="${(state.nodes[0].x+state.nodes[1].x)/2}" y="74" text-anchor="middle">−</text>`:`<text class="operation-sign" x="${(state.nodes[0].x+state.nodes[1].x)/2}" y="74" text-anchor="middle">+</text>`}${branchSigns()}${state.nodes.map(n=>`<g data-node="${n.id}" transform="translate(${n.x},${n.y})" tabindex="0" role="button" aria-label="${n.value}${n.fixed?', sustraendo, no se descompone':n.removed?', tachado':n.active?', disponible':', descompuesto o reunido'}" aria-pressed="${selected.includes(n.id)}" class="node ${n.fixed?'operand':''} ${n.active?'available':'past'} ${selected.includes(n.id)?'selected':''} ${n.removed?'removed':''}"><rect class="hit-area" x="-43" y="-33" width="86" height="66" rx="20"/><text text-anchor="middle" y="9">${n.value}</text>${n.circled&&op.mode==='subtract'?'<ellipse class="circle-mark" rx="49" ry="38" transform="rotate(-7)"/>':''}${n.removed?'<path class="cross-mark" d="M-32 21L32 -21"/>':''}</g>`).join('')}`}
function bindTree(){const svg=$('#graph');let drag=null,lastMoved=false;
 svg.onpointerdown=e=>{const g=e.target.closest('[data-node]');if(!g)return;const n=state.nodes.find(n=>n.id===Number(g.dataset.node));if(n.fixed){toast('Este es el sustraendo: indica cuánto hay que quitar. Las ramas solo salen del minuendo.');return}drag={id:n.id,startX:e.clientX,startY:e.clientY,x:n.x,y:n.y,snapshot:structuredClone(state),moved:false};svg.setPointerCapture(e.pointerId);e.preventDefault()};
 svg.onpointermove=e=>{if(!drag)return;const scale=svg.getBoundingClientRect().width/svg.viewBox.baseVal.width;const dx=(e.clientX-drag.startX)/scale,dy=(e.clientY-drag.startY)/scale;if(Math.abs(dx)+Math.abs(dy)<5&&!drag.moved)return;drag.moved=true;const n=state.nodes.find(n=>n.id===drag.id);n.x=Math.max(52,Math.min(848,drag.x+dx));n.y=drag.y;renderGraph()};
 svg.onpointerup=e=>{if(!drag)return;const id=drag.id;if(drag.moved){undo.push(drag.snapshot);lastMoved=true;$('#undo').disabled=false}else{const n=state.nodes.find(n=>n.id===id);if(n.active&&!done())selected=selected.includes(id)?selected.filter(v=>v!==id):[...selected,id];renderGraph();updateSelection()}drag=null};svg.onpointercancel=()=>drag=null;
 svg.onkeydown=e=>{const g=e.target.closest('[data-node]');if(!g)return;const n=state.nodes.find(n=>n.id===Number(g.dataset.node));if(n.fixed){if(['Enter',' '].includes(e.key)){e.preventDefault();toast('El sustraendo no se descompone: rodea el minuendo o una de sus ramas.')}return}if(['Enter',' '].includes(e.key)){e.preventDefault();if(n.active&&!done()){selected=selected.includes(n.id)?selected.filter(v=>v!==n.id):[...selected,n.id];renderGraph();updateSelection();svg.querySelector(`[data-node="${n.id}"]`).focus()}}else if(e.key.startsWith('Arrow')){e.preventDefault();undo.push(structuredClone(state));n.x=Math.max(52,Math.min(848,n.x+({'ArrowLeft':-10,'ArrowRight':10}[e.key]||0)));renderGraph();svg.querySelector(`[data-node="${n.id}"]`).focus();$('#undo').disabled=false}};
 $('#fit').onclick=()=>{zoom=.2;renderGraph();$('#graph-scroll').scrollLeft=0};$('#zoom-out').onclick=()=>{zoom=Math.max(.15,zoom-.1);renderGraph()};$('#zoom-in').onclick=()=>{zoom=Math.min(1.3,zoom+.1);renderGraph()};$('#arrange').onclick=()=>{undo.push(structuredClone(state));state=alignTree(state);renderGraph();$('#undo').disabled=false};
 $('#circle').onclick=()=>{try{const id=selected[0];commit(circleNode(state,id));selected=[id];renderGraph();updateSelection()}catch(e){sound('wrong');toast(e.message)}};
 $('#remaining').onclick=()=>{selected=activeNodes(state).map(n=>n.id);renderGraph();updateSelection();openMerge()};$('#split').onclick=()=>openSplit();$('#merge').onclick=()=>{if(op.mode==='subtract'&&state.removed===op.b&&selected.length<2){selected=activeNodes(state).map(n=>n.id);renderGraph();updateSelection()}openMerge()};$('#remove').onclick=()=>{try{commit(removeNodes(state,selected))}catch(e){sound('wrong');toast(e.message)}}}
function field(label,id,placeholder=''){return `<label>${esc(label)}<input id="${id}" name="${id}" type="number" inputmode="numeric" min="0" step="1" required placeholder="${esc(placeholder)}" autocomplete="off"></label>`}
function editor(label,title,copy,fields,action){$('#editor-label').textContent=label;$('#editor-title').textContent=title;$('#editor-copy').textContent=copy;$('#editor-fields').innerHTML=fields;$('#editor-error').textContent='';editorAction=action;dialog.showModal();setTimeout(()=>dialog.querySelector('input')?.focus(),30)}
function values(ids){return ids.map(id=>{const text=$('#'+id).value.trim();if(text==='')throw Error('Completa todas las casillas.');return Number(text)})}
function openSplit(){const n=state.nodes.find(n=>n.id===selected[0]);let count=2;const show=()=>{editor('SEPARAR',`${n.value} =` ,'Elige tus propias partes. Deben conservar la cantidad original.',`<div class="part-count">${[2,3,4,5,6].map(parts=>`<button type="button" data-parts="${parts}" aria-pressed="${count===parts}">${parts} ramas</button>`).join('')}</div><div class="field-row split-fields">${Array.from({length:count},(_,i)=>field('Parte '+(i+1),'part-'+i)).join('')}</div>`,()=>splitNode(state,n.id,values(Array.from({length:count},(_,i)=>'part-'+i))));dialog.querySelectorAll('[data-parts]').forEach(b=>b.onclick=()=>{count=Number(b.dataset.parts);dialog.close();show()})};show()}
function openMerge(){const ns=selected.map(id=>state.nodes.find(n=>n.id===id));editor('JUNTAR',`${ns.map(n=>n.value).join(' + ')} = ?`,'Calcula la cantidad reunida. Dibujaremos las conexiones que tú has elegido.',field('Total reunido','merge-answer'),()=>mergeNodes(state,selected,values(['merge-answer'])[0]))}
$('#editor-form').onsubmit=e=>{e.preventDefault();try{const next=editorAction();dialog.close();commit(next)}catch(error){sound('wrong');$('#editor-error').textContent=error.message}};$('#close-editor').onclick=()=>dialog.close();
function climbHtml(){const reached=state.current===op.a,started=state.current!==null;const path=started?`<button type="button" class="path-start ${state.crossedStart?'crossed':''}" id="climb-written-start" aria-label="${state.start}${state.crossedStart?', tachado':''}" ${!reached||state.crossedStart?'disabled':''}>${state.start}</button>${state.jumps.map(j=>`<span class="path-plus">+</span><button type="button" class="path-jump" data-climb-part aria-label="Número ${j.amount}" ${!reached||state.crossedStart?'disabled':''}>${j.amount}</button>`).join('')}`:'<span class="path-pending">□</span>';
return `<div class="paper-climb"><div class="paper-math"><div class="written-path"><div class="path-numbers">${path}</div>${state.branched?`<svg class="gather-lines" aria-hidden="true"></svg><div class="path-total"><span class="path-total-number">${state.finished?op.a-op.b:'?'}</span></div>`:''}</div><div class="written-equal">=</div><div class="vertical-operation"><div class="minuend">${op.a}</div><div class="subtrahend"><span>−</span>${op.b}</div><div class="vertical-answer">${state.finished?op.a-op.b:'?'}</div></div></div>${!done()?!started?`<form id="climb-start-form">${field('Punto de partida','climb-start-value')}<button class="primary">Escribir ✓</button><div id="climb-error" role="alert"></div></form>`:reached?`<div class="roc-tools"><button id="climb-cross-tool" class="secondary" aria-pressed="${!!state.crossTool}" ${state.crossedStart?'disabled':''}>╱ Tachar</button><button id="branch-jumps" class="secondary" ${!state.crossedStart||state.branched?'disabled':''}>⋁ Ramificar</button></div>${state.branched?`<form id="finish-form">${field('Resultado','total-jumps')}<button class="primary">Comprobar ✓</button><div id="climb-error" role="alert"></div></form>`:''}`:`<form id="jump-form"><div class="field-row">${field('Salto +','jump-size')}${field('Llego a','jump-landing')}</div><button class="primary">Escribir salto ↑</button><div id="climb-error" role="alert"></div></form>`:''}</div>`}
function alignClimbBranches(){const draw=()=>{const math=$('.paper-math'),parent=$('.written-path'),row=$('.path-numbers');if(!math||!parent||!row)return;math.style.width='100%';math.style.minWidth='0';const css=getComputedStyle(math),gap=parseFloat(css.columnGap)||0,vertical=$('.vertical-operation').getBoundingClientRect().width,equal=$('.written-equal').getBoundingClientRect().width;const terms=[...row.children],rowGap=parseFloat(getComputedStyle(row).columnGap)||0,natural=terms.reduce((sum,e)=>sum+e.getBoundingClientRect().width,0)+Math.max(0,terms.length-1)*rowGap;const available=math.parentElement.clientWidth-parseFloat(getComputedStyle(math.parentElement).paddingLeft)-parseFloat(getComputedStyle(math.parentElement).paddingRight);math.style.width=Math.max(available,natural+vertical+equal+2*gap+4)+'px';const svg=$('.gather-lines'),target=$('.path-total-number'),total=$('.path-total'),jumps=[...parent.querySelectorAll('.path-jump')];if(!svg||!target||!jumps.length)return;const base=parent.getBoundingClientRect(),positions=jumps.map(e=>e.getBoundingClientRect()),centres=positions.map(r=>r.left+r.width/2-base.left),middle=(Math.min(...centres)+Math.max(...centres))/2;target.style.position='relative';target.style.left='0px';const t=target.getBoundingClientRect();target.style.left=(middle-(t.left-base.left)-t.width/2)+'px';const end=target.getBoundingClientRect();svg.setAttribute('viewBox',`0 0 ${base.width} ${base.height}`);svg.setAttribute('preserveAspectRatio','none');svg.innerHTML=positions.map((r,i)=>`<path d="M${centres[i]} ${r.bottom-base.top+5} L${middle} ${end.top-base.top-7}"/>`).join('')};draw();requestAnimationFrame(draw)}
function bindClimb(){app.querySelectorAll('[data-climb-part]').forEach(b=>b.onclick=()=>{if(state.crossTool){sound('wrong');toast('Revisa qué cantidad tienes que tachar.')}});const beginning=$('#climb-start-form');if(beginning)beginning.onsubmit=e=>{e.preventDefault();try{commit(setClimbStart(state,values(['climb-start-value'])[0]))}catch(e){sound('wrong');$('#climb-error').textContent=e.message}};const cross=$('#climb-written-start');if(cross)cross.onclick=()=>{if(!state.crossTool)return;try{commit(crossClimbStart(state))}catch(e){sound('wrong');toast(e.message)}};const tool=$('#climb-cross-tool');if(tool)tool.onclick=()=>{state.crossTool=!state.crossTool;workspace()};const branch=$('#branch-jumps');if(branch)branch.onclick=()=>{try{commit(branchClimb(state))}catch(e){sound('wrong');toast(e.message)}};const jump=$('#jump-form');if(jump)jump.onsubmit=e=>{e.preventDefault();try{const [a,b]=values(['jump-size','jump-landing']);commit(addJump(state,a,b))}catch(error){sound('wrong');$('#climb-error').textContent=error.message}};const final=$('#finish-form');if(final)final.onsubmit=e=>{e.preventDefault();try{commit(finishClimb(state,values(['total-jumps'])[0]))}catch(error){sound('wrong');$('#climb-error').textContent=error.message}}}
function learn(){app.innerHTML=`<section class="learn"><span class="eyebrow">NO HAY UN SOLO CAMINO</span><h1>Piensa con números.<br><em>Dibuja tus ideas.</em></h1><p>El objetivo es construir el algoritmo, no solo escribir un resultado. Toda descomposición que conserve la cantidad es válida.</p><div class="lesson-grid"><article><span>🌳</span><h2>Suma en árbol</h2><p>Abre ramas para separar los sumandos. Puedes usar decenas y unidades, mitades u otras partes. Selecciona cantidades, calcula su suma y reúnelas en nuevos nodos.</p><p class="example">48 + 27 → (40 + 8) + (20 + 7) → 60 + 15 → 75</p><button class="secondary" data-demo="add">Explorar un ejemplo →</button></article><article><span>🌿</span><h2>Resta en árbol</h2><p>Rodea el número que vas a descomponer. Abre sus ramas y tacha dentro del mismo árbol las partes que forman el sustraendo. Puedes tacharlas en varios pasos. Después reúne lo que queda.</p><p class="example">74 − 28: 74 = 60 + 14; 60 = 20 + 40; 14 = 8 + 6. Tacha 20 y 8. Quedan 40 + 6.</p><button class="secondary" data-demo="subtract">Explorar un ejemplo →</button></article><article><span>🧗</span><h2>Rocódromo</h2><p>Empieza en el sustraendo y sube hasta el minuendo. Decide los saltos y calcula dónde apoyarte. Al final, reúne lo que has subido: esa distancia es la diferencia.</p><p class="example">83 − 46: 46 → 50 (+4) → 80 (+30) → 83 (+3). La diferencia es 4 + 30 + 3.</p><button class="secondary" data-demo="climb">Explorar un ejemplo →</button></article><article><span>👗</span><h2>Suma en vestidos</h2><p>Escribe cada sumando en vertical y descompón a su derecha en centenas, decenas y unidades. Suma debajo de cada vestido y escribe el resultado final a la derecha del igual.</p><button class="secondary" data-demo="dresses">Explorar un ejemplo →</button></article><article><span>💰</span><h2>Sacos de Paco</h2><p>Junta las cantidades del saco y escribe cuánto hay. En los niveles 3 y 4, redondea primero a decenas y compara la estimación con el resultado exacto.</p><button class="secondary" data-demo="sacks">Explorar un ejemplo →</button></article><article><span>🎯</span><h2>Reto de Paco</h2><p>Observa los sacos y encuentra la cantidad de la meta. En los niveles 3 y 4, busca todos los que se aproximan a ella al redondear a decenas.</p><button class="secondary" data-demo="sackhunt">Explorar un ejemplo →</button></article><article><span>🔵</span><h2>Número de veces</h2><p>Cada tapón representa un grupo y las bolas representan lo que hay dentro. Completa el diagrama y escribe primero las veces y después la cantidad en cada grupo.</p><button class="secondary" data-demo="multiply">Explorar un ejemplo →</button></article></div><p class="learn-note">Puedes arrastrar los nodos, deshacer pasos y probar otro camino. Las operaciones nuevas no se repiten en este navegador; los ejemplos de ayuda sí se pueden volver a explorar.</p><button id="back-home" class="primary">Elegir mi ruta →</button></section>`;$('#back-home').onclick=home;app.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>{const kind=b.dataset.demo;if(kind==='multiply'){difficulty=1;digits=2;op={mode:kind,level:1,digits:2,a:20,b:5};mode=kind;demo=true;awarded=false;startState();return}if(['dresses','sacks','sackhunt'].includes(kind)){difficulty=3;digits=3;op={mode:kind,digits:3,level:3,a:138,b:245};mode=kind;demo=true;awarded=false;startState();return}op=kind==='add'?{mode:kind,digits:2,a:48,b:27}:kind==='subtract'?{mode:kind,digits:2,a:74,b:28}:{mode:kind,digits:2,a:83,b:46};mode=kind;demo=true;awarded=false;startState()});window.scrollTo({top:0,behavior:'smooth'})}
$('#home-link').onclick=e=>{e.preventDefault();if(!op||done()||confirm('¿Volver a elegir una ruta? El camino actual no se guardará.'))home()};$('#learn-link').onclick=()=>{if(!op||done()||confirm('¿Abrir la ayuda? El camino actual no se guardará.')){op=null;learn()}};
let previousWidth=window.innerWidth;window.addEventListener('resize',()=>{if(window.innerWidth===previousWidth)return;previousWidth=window.innerWidth;if(op&&['add','subtract'].includes(op.mode)){zoom=window.innerWidth<650?.2:.9;requestAnimationFrame(()=>{renderGraph();const pane=$('#graph-scroll');if(pane)pane.scrollLeft=0})}else if(op?.mode==='climb'){requestAnimationFrame(alignClimbBranches)}});
