function leaveGame(callback){if(op&&!done()&&!confirm('¿Salir de esta operación? Quedará registrada como iniciada.'))return;op=null;callback()}
function modeOptions(selected){return Object.entries(LABELS).map(([value,label])=>`<option value="${value}" ${value===selected?'selected':''}>${label}</option>`).join('')}
function levelOptions(selected){return DIFFICULTIES.map(l=>`<option value="${l.id}" ${l.id===Number(selected)?'selected':''}>${l.id} · ${l.label}</option>`).join('')}
async function showRanking(selectedMode='all',selectedLevel='all'){op=null;app.innerHTML=`<section class="ranking-page"><span class="eyebrow">JUNTOS APRENDEMOS MÁS</span><h1>🏆 Nuestro ranking</h1><p>Sumas puntos cada vez que completas una operación: nivel 1, 100; nivel 2, 200; nivel 3, 300; nivel 4, 400. Además, hasta 50 por rapidez.</p><p>El ranking general suma todas las pruebas y niveles. Usa los filtros para ver tu curso, clase o prueba.</p><div class="rank-filters"><label>Colegio<select id="rank-school">${schoolOptions('all',true)}</select></label><label>Curso<select id="rank-course"><option value="all">Todos los cursos</option>${courseOptions("all")}</select></label><label>Clase<select id="rank-room">${rankClassOptions("all")}</select></label><label>Prueba<select id="rank-mode"><option value="all">Todas las pruebas</option>${modeOptions(selectedMode)}</select></label><label>Nivel<select id="rank-level"><option value="all">Todos los niveles</option>${levelOptions(selectedLevel)}</select></label><button id="refresh-ranking" class="secondary">↻ Actualizar</button></div><div id="rank-list" aria-live="polite"></div><button id="ranking-home" class="primary">¡A jugar! →</button></section>`;let requestId=0;const refresh=async()=>{const revision=++requestId;const box=$('#rank-list');box.innerHTML='<p>Cargando…</p>';try{const q=new URLSearchParams({school:$('#rank-school').value,room:$('#rank-room').value,mode:$('#rank-mode').value,level:$('#rank-level').value}),r=await fetch('/api/math?'+q);const d=await r.json();if(revision!==requestId||!document.contains(box))return;if(!r.ok)throw Error(d.error);box.innerHTML=d.rows.length?`<div class="ranking-table">${d.rows.map((row,i)=>`<div class="ranking-row"><b>${i<3?['🥇','🥈','🥉'][i]:i+1}</b><span class="rank-person">${avatarSvg(row.avatar||{},"Avatar de "+row.name)}<span>${esc(row.name)}${row.code?' <small>Perfil protegido</small>':''}<small>${esc(schoolName(row.school))} · ${row.room?row.room[0]+'º'+row.room[1]+' · ':''}${row.operations} operaciones</small></span></span><strong>${row.points} pts</strong></div>`).join('')}</div>`:'<div class="empty-state">🌱 Aún no hay puntos con estos filtros. ¡Puedes empezar tú!</div>'}catch(e){box.textContent=e.message}};$('#rank-course').onchange=()=>{$('#rank-room').innerHTML=rankClassOptions($('#rank-course').value);refresh()};for(const id of ['rank-school','rank-room','rank-mode','rank-level'])$('#'+id).onchange=refresh;$('#refresh-ranking').onclick=refresh;$('#ranking-home').onclick=home;await refresh();window.scrollTo({top:0,behavior:'smooth'})}
function mondayNow(){const day=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Madrid',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());const date=new Date(day+'T12:00:00Z');date.setUTCDate(date.getUTCDate()-(date.getUTCDay()+6)%7);return date.toISOString().slice(0,10)}
function showTeacher(){wordSession=null;op=null;showTeacherMenu()}
function showTeacherMenu(){app.innerHTML=`<section class="account-page"><span class="eyebrow">ÁREA DEL PROFESOR</span><h1>Profesor</h1><p>Elige qué quieres gestionar.</p><div class="account-actions"><button id="teacher-weekly" class="primary">Control semanal</button><button id="teacher-accounts" class="secondary">Gestión de cuentas</button></div></section>`;$('#teacher-weekly').onclick=showWeeklyAccess;$('#teacher-accounts').onclick=()=>window.oaoaOpenAccounts()}
function showWeeklyAccess(){op=null;if(!teacherSecret){app.innerHTML=`<section class="teacher-login"><span class="eyebrow">SOLO PARA EL PROFESOR</span><h1>Control semanal</h1><p>Consulta el trabajo registrado por tus alumnos.</p><form id="teacher-login"><label>Clave de profesor<input id="teacher-key" type="password" required autocomplete="current-password"></label><button class="primary">Entrar →</button><p id="teacher-error" role="alert"></p></form></section>`;$('#teacher-login').onsubmit=e=>{e.preventDefault();teacherSecret=$('#teacher-key').value;teacherPanel()};return}teacherPanel()}
async function teacherPanel(){app.innerHTML=`<section class="teacher-panel"><div class="teacher-heading"><div><span class="eyebrow">ACTIVIDAD DE LA CLASE</span><h1>Control semanal</h1></div><button id="teacher-logout" class="secondary">Cerrar panel</button></div><p>El ranking general suma todas las pruebas y niveles. Usa los filtros para ver tu curso, clase o prueba.</p><div class="rank-filters"><label>Colegio<select id="weekly-school">${schoolOptions(playerSchool)}</select></label><label>Clase<select id="weekly-room">${classOptions(playerRoom,true)}</select></label><label>Semana del<input type="date" id="weekly-date" value="${mondayNow()}"></label><button id="week-before" class="secondary">← Anterior</button><button id="week-after" class="secondary">Siguiente →</button><button id="export-week" class="primary" disabled>Descargar CSV ↓</button></div><p id="week-label"></p><div id="weekly-summary" class="weekly-summary"></div><div id="weekly-list" aria-live="polite"></div><p class="report-note">Se registra actividad desde esta actualización. El tiempo corresponde a operaciones completadas y puede incluir pausas. Usa siempre el mismo nombre o alias para cada alumno.</p></section>`;
 $('#teacher-logout').onclick=()=>{teacherSecret='';weeklyData=null;home()};let requestId=0;const refresh=async()=>{const revision=++requestId;const box=$('#weekly-list');box.innerHTML='<p>Cargando semana…</p>';$('#export-week').disabled=true;try{const q=new URLSearchParams({school:$('#weekly-school').value,room:$('#weekly-room').value,week:$('#weekly-date').value}),r=await fetch('/api/weekly?'+q,{headers:{'X-Teacher-Key':teacherSecret}});const d=await r.json();if(revision!==requestId||!document.contains(box))return;if(!r.ok){if(r.status===401){teacherSecret='';showWeeklyAccess();$('#teacher-error').textContent=d.error;return}throw Error(d.error)}weeklyData=d;$('#weekly-date').value=d.week;$('#week-label').textContent=`Del ${d.week.split('-').reverse().join('/')} al ${new Date(Date.parse(d.next+'T12:00:00Z')-86400000).toISOString().slice(0,10).split('-').reverse().join('/')}`;const completed=d.rows.reduce((s,r)=>s+r.completed,0),begun=d.rows.reduce((s,r)=>s+r.started,0);$('#weekly-summary').innerHTML=`<div><strong>${d.rows.length}</strong><span>alumnos activos</span></div><div><strong>${begun}</strong><span>operaciones iniciadas</span></div><div><strong>${completed}</strong><span>operaciones completadas</span></div>`;box.innerHTML=d.rows.length?`<div class="report-scroll"><table><thead><tr><th>Alumno</th><th>Iniciadas</th><th>Completadas</th><th>Días activos</th><th>Sumas</th><th>Restas</th><th>Rocódromo</th><th>Vestidos</th><th>Sacos</th><th>Reto de Paco</th><th>Multiplicación</th><th>Tiempo registrado</th><th>Puntos</th></tr></thead><tbody>${d.rows.map(r=>`<tr><th>${esc(r.name)}</th><td>${r.started}</td><td><b>${r.completed}</b></td><td>${r.days}</td><td>${r.add}</td><td>${r.subtract}</td><td>${r.climb}</td><td>${r.dresses||0}</td><td>${r.sacks||0}</td><td>${r.sackhunt||0}</td><td>${r.multiply||0}</td><td>${clockText(r.seconds*1000)}</td><td>${r.points}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty-state">No hay actividad registrada en esta clase durante esta semana.</div>';$('#export-week').disabled=!d.rows.length}catch(e){box.textContent=e.message}};
 $('#weekly-school').onchange=refresh;$('#weekly-room').onchange=refresh;$('#weekly-date').onchange=refresh;const shift=amount=>{const date=new Date($('#weekly-date').value+'T12:00:00Z');date.setUTCDate(date.getUTCDate()+amount);$('#weekly-date').value=date.toISOString().slice(0,10);refresh()};$('#week-before').onclick=()=>shift(-7);$('#week-after').onclick=()=>shift(7);$('#export-week').onclick=()=>{if(!weeklyData)return;const cell=v=>'"'+String(v).replace(/^[=+@-]/,"'$&").replaceAll('"','""')+'"';const csv='\ufeff'+[['Alumno','Iniciadas','Completadas','Días activos','Sumas','Restas','Rocódromo','Vestidos','Sacos','Reto de Paco','Multiplicación','Tiempo en segundos','Puntos'],...weeklyData.rows.map(r=>[r.name,r.started,r.completed,r.days,r.add,r.subtract,r.climb,r.dresses||0,r.sacks||0,r.sackhunt||0,r.multiply||0,r.seconds,r.points])].map(row=>row.map(cell).join(',')).join('\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`actividad-${weeklyData.room}-${weeklyData.week}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};await refresh();window.scrollTo({top:0,behavior:'smooth'})}

function extraWorkspace(){const complete=done();app.innerHTML=`<section class="work-head"><div><span class="eyebrow">${demo?'EJEMPLO':`NIVEL ${difficulty} · ${playerRoom[0]+'º'+playerRoom[1]}`}</span><h1>${LABELS[op.mode]}</h1><span id="game-clock" class="game-clock" role="timer"></span></div>${op.mode==='dresses'?`<div class="operation">${op.a} + ${op.b} = <strong>${complete?op.a+op.b:'?'}</strong></div>`:''}</section><section class="workspace extra-workspace"><div class="workspace-top"><span>${op.mode==='dresses'?'👗 DESCOMPÓN · SUMA':'💰 LOS SACOS DE PACO'}</span><button id="undo" ${!undo.length||complete?'disabled':''}>↶ Deshacer</button></div>${extraHtml(state,selected)}<p id="extra-error" role="alert" class="extra-error"></p>${complete?`<div class="success">${celebrationHtml()}<span>✦ ¡BIEN HECHO!</span><h2>¡Lo has conseguido!</h2><div id="record-status" class="record-status" aria-live="polite"></div><div class="actions"><button id="next" class="primary">Otra operación →</button><button id="another" class="secondary">Otra forma</button></div></div>`:''}<details class="steps-details"><summary>Mis pasos</summary><ol>${state.log.map(l=>`<li>${esc(l)}</li>`).join('')}</ol></details></section>`;$('#undo').onclick=()=>{if(undo.length){state=undo.pop();selected=[];extraWorkspace()}};if(complete){$('#next').onclick=newExercise;$('#another').onclick=startState;updateRecord()}else bindExtra(state,selected,{commit,select:id=>{selected=selected.includes(id)?selected.filter(v=>v!==id):[...selected,id];extraWorkspace()},error:message=>{sound('wrong');$('#extra-error').textContent=message}});updateClock()}

function multiplicationWorkspace(){const complete=done();app.innerHTML=`<section class="work-head"><div><span class="eyebrow">${demo?'EJEMPLO':`NIVEL ${difficulty} · ${playerRoom[0]}º${playerRoom[1]}`}</span><h1>Multiplicación · Número de veces</h1><span id="game-clock" class="game-clock" role="timer"></span></div><button id="mul-undo" class="secondary" ${!undo.length||complete?'disabled':''}>↶ Deshacer</button></section><div class="mul-workspace">${multiplicationHtml(state)}<p id="mul-error" role="alert" tabindex="-1"></p>${complete?`<div class="success">${celebrationHtml()}<span>✦ ¡BIEN HECHO!</span><h2>¡Lo has conseguido!</h2><p>${state.problem.times} veces ${state.problem.repeated} ${state.problem.item}.</p><div id="record-status" class="record-status" aria-live="polite"></div><div class="actions"><button id="next" class="primary">Otro problema →</button><button id="another" class="secondary">Otra forma</button></div></div>`:''}<details class="steps-details"><summary>Mis pasos</summary><ol>${state.log.map(l=>`<li>${esc(l)}</li>`).join('')}</ol></details></div>`;$('#mul-undo').onclick=()=>{if(undo.length){state=undo.pop();multiplicationWorkspace()}};if(complete){$('#next').onclick=newExercise;$('#another').onclick=startState;updateRecord()}else bindMultiplication(state,{commit,draft:next=>{undo.push(structuredClone(state));state=next;multiplicationWorkspace()},error:message=>{sound('wrong');$('#mul-error').textContent=message;$('#mul-error').scrollIntoView({block:'nearest',behavior:'smooth'})}});updateClock()}

function wordWorkspace(){
 const w=wordSession,p=w.problem,labels={add:'Árbol de suma',subtract:'Árbol de resta',climb:'Rocódromo',dresses:'Vestidos'};
 const step=w.stage==='diagram'?0:w.stage==='operation'?1:w.stage==='calculate'?2:3;
 app.innerHTML=`<section class="word-adventure"><div class="word-story"><span class="eyebrow">MISIÓN · PROBLEMAS DE SUMA Y RESTA</span><h1>Piensa la historia</h1><p>${esc(p.text)}</p><span id="game-clock" class="game-clock" role="timer"></span></div><ol class="word-progress">${['Diagrama','Operación','Cálculo','Solución'].map((t,i)=>`<li ${i===step?'aria-current="step"':''} class="${i<step?'passed':''}">${i+1} · ${t}</li>`).join('')}</ol><section class="word-panel">${w.stage==='diagram'?`<h2>1. Representa lo que sabes</h2><p>Elige el dibujo. Coloca los datos y escribe <b>?</b> en la cantidad que buscamos.</p><div class="word-models"><button class="secondary" data-word-model="parts" aria-pressed="${w.model==='parts'}">Partes y todo</button><button class="secondary" data-word-model="bars" aria-pressed="${w.model==='bars'}">Diagrama de barras</button></div>${wordDiagramHtml(p,w.model,w.values)}<button id="word-check" class="primary">Comprobar diagrama →</button>`:w.stage==='operation'?`<h2>2. ¿Qué necesitas calcular?</h2>${wordDiagramHtml(p,w.model,w.values,true)}<div class="word-models"><button class="primary" data-word-operation="add">Sumar +</button><button class="primary" data-word-operation="subtract">Restar −</button></div>${w.operationChecked?`<h3>Elige cómo resolverlo</h3><div class="word-models">${problemMethods(p).map(m=>`<button class="secondary" data-word-method="${m}">${labels[m]}</button>`).join('')}</div>`:''}`:`<h2>4. Responde a la pregunta</h2><p>Ya has hecho el cálculo. Ahora completa la solución con su unidad.</p><form id="word-answer-form"><label class="word-sentence"><span>${esc(p.before)}</span><input id="word-answer" type="number" inputmode="numeric" min="0" step="1" aria-label="Número de la solución" required><span>${esc(p.after)}</span></label><button class="primary">Comprobar solución ✓</button></form>`}<p id="word-error" role="alert"></p></section></section>`;
 const error=e=>{sound('wrong');$('#word-error').textContent=e.message};
 const read=()=>w.values=[...app.querySelectorAll('[data-word-value]')].map(i=>i.value);
 app.querySelectorAll('[data-word-model]').forEach(b=>b.onclick=()=>{read();w.model=b.dataset.wordModel;wordWorkspace()});
 const check=$('#word-check');if(check)check.onclick=()=>{try{read();checkWordDiagram(p,w);w.steps=[{type:'problemDiagram',model:w.model,values:[...w.values]}];w.stage='operation';sound('correct');wordWorkspace()}catch(e){error(e)}};
 app.querySelectorAll('[data-word-operation]').forEach(b=>b.onclick=()=>{try{if(b.dataset.wordOperation!==p.operation)throw Error('Piensa si buscas el total o una parte o diferencia. Revisa el diagrama.');w.operationChecked=true;w.steps=w.steps.slice(0,1).concat({type:'problemOperation',operation:p.operation});sound('correct');wordWorkspace()}catch(e){error(e)}});
 app.querySelectorAll('[data-word-method]').forEach(b=>b.onclick=()=>{w.steps=w.steps.slice(0,2).concat({type:'problemMethod',method:b.dataset.wordMethod});w.stage='calculate';op={...w.seed,mode:b.dataset.wordMethod};startState()});
 const form=$('#word-answer-form');if(form)form.onsubmit=e=>{e.preventDefault();try{const value=$('#word-answer').value;if(value.trim()===''||!Number.isSafeInteger(Number(value))||Number(value)!==p.answer)throw Error('Revisa el número y vuelve a leer la pregunta.');w.answer=Number(value);awarded=true;timerStopped=elapsedNow();solved++;saveHistory();sound('complete');app.innerHTML=`<section class="word-panel word-finished">${celebrationHtml()}<span class="eyebrow">MISIÓN COMPLETADA</span><h1>¡Historia resuelta!</h1><p>${esc(p.text)}</p><h2>${esc(p.before)} ${w.answer} ${esc(p.after)}</h2>${wordDiagramHtml(p,w.model,w.values.map((v,i)=>v==='?'?w.answer:v),true)}<div id="record-status" aria-live="polite"></div><button id="next" class="primary">Otro problema →</button></section>`;$('#next').onclick=()=>{mode='problems';newExercise()};void saveRecord()}catch(e){error(e)}};
 updateClock();window.scrollTo({top:0,behavior:'smooth'});
}

function celebrationHtml(){const a=window.oaoaAccount;let avatar={};try{avatar=typeof a?.avatar==='string'?JSON.parse(a.avatar):a?.avatar||{}}catch{}return `<div class="pupil-celebration">${avatarSvg({...avatar,motion:'thumb'},a?'Tu avatar te felicita':'Personaje de bienvenida')}<div><strong>¡Enhorabuena${a?', '+esc(a.name):''}!</strong><p>Has pensado, construido y encontrado tu camino.</p></div></div>`}
